export class RateLimiter {
  constructor(limit, windowMs) {
    this.limit = limit;
    this.windowMs = windowMs;
    this.counts = new Map();
  }

  allow(key) {
    const window = Math.floor(Date.now() / this.windowMs);
    const bucket = `${key}:${window}`;
    const used = this.counts.get(bucket) ?? 0;

    if (used >= this.limit) return false;
    this.counts.set(bucket, used + 1);
    return true;
  }
}

export class LruCache {
  constructor(max) {
    this.max = max;
    this.map = new Map();
  }

  get(key) {
    return this.map.get(key);
  }

  set(key, value) {
    if (this.map.size >= this.max && !this.map.has(key)) {
      const oldest = this.map.keys().next().value;
      this.map.delete(oldest);
    }
    this.map.set(key, value);
  }
}

export class Emitter {
  constructor() {
    this.handlers = new Map();
  }

  on(event, handler) {
    const list = this.handlers.get(event) ?? [];
    list.push(handler);
    this.handlers.set(event, list);
  }

  emit(event, payload) {
    for (const handler of this.handlers.get(event) ?? []) {
      handler(payload);
    }
  }
}

export function dispatch(handlers, payload) {
  for (const handler of handlers) {
    handler(payload);
  }
  return { delivered: handlers.length };
}

const DEFAULTS = { headers: {}, retries: 2 };

export function buildRequest(overrides = {}) {
  const config = { ...DEFAULTS, ...overrides };
  config.headers['x-request-id'] = crypto.randomUUID();
  return config;
}

export async function withRetry(operation, attempts = 3) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      return await operation();
    } catch (error) {
      lastError = error;
      await sleep(2 ** i * 100);
    }
  }
  throw lastError;
}

export class ParkingLot {
  constructor(spots) {
    this.free = new Set(spots);
  }

  async allocate(vehicleId, persist) {
    const spot = this.free.values().next().value;
    if (!spot) return null;

    await persist(vehicleId, spot);

    this.free.delete(spot);
    return spot;
  }
}

let lastMs = 0;
let counter = 0;

export function nextId() {
  const now = Date.now();
  if (now !== lastMs) {
    lastMs = now;
    counter = 0;
  }
  return `${now}-${counter++}`;
}

