CREATE TABLE post (
  id             uuid PRIMARY KEY,
  comment_count  integer NOT NULL DEFAULT 0
);

-- comment creation path
BEGIN;
  INSERT INTO comment (post_id, body) VALUES ($1, $2);
  UPDATE post SET comment_count = comment_count + 1 WHERE id = $1;
COMMIT;

-- comment deletion path (moderation tool)
DELETE FROM comment WHERE id = $1;

SELECT p.id, p.comment_count, count(c.id)
FROM post p LEFT JOIN comment c ON c.post_id = p.id
GROUP BY p.id, p.comment_count
HAVING p.comment_count <> count(c.id);
-- 1,284 rows

CREATE TABLE workspace (id uuid PRIMARY KEY);

CREATE TABLE document (
  id            uuid PRIMARY KEY,
  workspace_id  uuid NOT NULL,
  title         text NOT NULL
);

-- no foreign key on document.workspace_id

SELECT count(*) FROM document d
LEFT JOIN workspace w ON w.id = d.workspace_id
WHERE w.id IS NULL;
-- 7,412
